import sys

def solve():
    days = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']
    day_to_int = {day:i for i, day in enumerate(days)}
    days_in_month = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    line1 = sys.stdin.readline().strip()
    line2 = sys.stdin.readline().strip()
    day1 = day_to_int[line1]
    day2 = day_to_int[line2]
    for i in range(11):  # check consecutive months (Jan-Feb, ..., Nov-Dec)
        shift = days_in_month[i] % 7
        if (day1 + shift) % 7 == day2:
            print("YES")
            return
    print("NO")

if __name__ == "__main__":
    solve()
"}

