import sys

def get_divisors(n):
    """Return a set of all divisors of n"""
    divisors = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return divisors

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])

    # Precompute all divisors for numbers up to max_x
    max_x = 0
    queries = []
    for i in range(1, n + 1):
        x = int(data[1 + 2 * (i - 1)])
        y = int(data[2 + 2 * (i - 1)])
        queries.append((x, y))
        if x > max_x:
            max_x = x

    # Precompute divisors for all numbers up to max_x
    divisors = {}
    for num in range(1, max_x + 1):
        divisors[num] = get_divisors(num)

    # Process each query
    for i, (x, y) in enumerate(queries, 1):
        if y == 0:
            # Count all divisors of x
            count = len(divisors[x])
        else:
            # Find divisors of x
            current_divisors = divisors[x]

            # Check previous numbers x - y to x - 1
            previous_numbers = range(x - y, x)

            # Count how many divisors of x do NOT divide any previous number
            count = 0
            for d in current_divisors:
                divides_any = False
                for num in previous_numbers:
                    if num % d == 0:
                        divides_any = True
                        break
                if not divides_any:
                    count += 1
        print(count)

if __name__ == "__main__":
    solve()
"}

