def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

# Read input
text = input().strip()
if not text:
    text = input().strip()

lines = text.split('\n')
n = int(lines[0])
a = list(map(int, lines[1].split()))

# Separate odds and evens
evens = [x for x in a if x % 2 == 0]
odds = [x for x in a if x % 2 == 1]

# Check if a number is prime up to max possible sum
max_sum = 2 * 10**6 + 1
primes = [True] * max_sum
primes[0] = primes[1] = False
for i in range(2, int(max_sum**0.5) + 1):
    if primes[i]:
        for j in range(i*i, max_sum, i):
            primes[j] = False

# Function to check if a list of numbers forms a simple subset
# This is O(k^2) where k is the size of the subset
def is_simple_subset(subset):
    for i in range(len(subset)):
        for j in range(i+1, len(subset)):
            if not primes[subset[i] + subset[j]]:
                return False
    return True

# Try all combinations with one even and multiple odds
best_size = 0
best_subset = []

for even in evens:
    # Find all odds that can pair with this even
    candidate_odds = [o for o in odds if primes[even + o]]

    # Now find the largest simple subset among these odds
    # This is still O(k^2) for each candidate
    for i in range(len(candidate_odds) + 1):
        for subset in itertools.combinations(candidate_odds, i):
            if is_simple_subset(list(subset)):
                combined = [even] + list(subset)
                if len(combined) > best_size:
                    best_size = len(combined)
                    best_subset = combined

# Try all combinations without any even
for i in range(len(odds) + 1):
    for subset in itertools.combinations(odds, i):
        if is_simple_subset(list(subset)):
            if len(subset) > best_size:
                best_size = len(subset)
                best_subset = list(subset)

# Output
print(best_size)
if best_size > 0:
    print(' '.join(map(str, best_subset)))
else:
    print()  # In case no subset found (shouldn't happen)

import itertools
"}

