    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    original_ones = sum(a)

    max_gain = 0

    # Try all subarrays [i, j]
    for i in range(n):
        for j in range(i, n):
            # Count zeros and ones in subarray a[i..j]
            zeros = 0
            ones = 0
            for k in range(i, j+1):
                if a[k] == 0:
                    zeros += 1
                else:
                    ones += 1

            gain = zeros - ones
            if gain > max_gain:
                max_gain = gain

    print(original_ones + max_gain)

if __name__ == "__main__":
    solve()
