def solve():
    n, m, k = map(int, input().split())

    # cost[i][j] = minimum cost to fix segment [i, j]
    cost = [[float('inf')] * (n + 1) for _ in range(n + 1)]

    # Read all companies
    for _ in range(m):
        l, r, c = map(int, input().split())
        if c < cost[l][r]:
            cost[l][r] = c

    # dp[i][j] = minimum cost to fix j holes among the first i holes
    dp = [[float('inf')] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for r in range(1, n + 1):
        for l in range(1, r + 1):
            holes = r - l + 1

            # Option 1: Fix segment [l, r]
            for j in range(holes, k + 1):
                dp[r][j] = min(dp[r][j], dp[l - 1][j - holes] + cost[l][r])

    print(dp[n][k] if dp[n][k] != float('inf') else -1)

solve()
