import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])

    questions = set()
    for i in range(2, 2 + k):
        questions.add(int(data[i]))

    safe = [i for i in range(1, n + 1) if i not in questions]
    m = len(safe)

    # Count valid (a, b) pairs where |a-b| <= 1 and both are safe
    # This is just the number of edges in a path graph with m vertices
    # which is m, but we need to be careful about the positions

    # Let's count pairs directly
    count = 0
    for i in range(m):
        for j in range(i, m):
            if abs(safe[i] - safe[j]) <= 1:
                count += 1

    print(count)

if __name__ == "__main__":
    solve()
"}

