    else:
        per_row = k // n
        extra = k % n
        row_diff = 1 if extra > 0 else 0
        min_f = 2 * row_diff

    # Construct grid
    if k == 0:
        grid = [[0 for _ in range(n)] for _ in range(n)]
    elif k == n * n:
        grid = [[1 for _ in range(n)] for _ in range(n)]
