            # Distribute ones_needed 1s as evenly as possible in this row
            row = [0] * n
            if ones_needed > 0:
                for col_idx in range(ones_needed):
                    row[col_idx] = 1
            grid.append(row)

    # Output
    print(min_f)
    for row in grid:
