import sys

def solve():
    n = int(sys.stdin.readline())
    lengths = list(map(int, sys.stdin.readline().split()))
    terrain = sys.stdin.readline().strip()

    # Initial stamina: 0
    # We need to track minimum time for each stamina value at each segment
    # dp[i][s] = minimum time to reach start of segment i with stamina s

    # Use a dictionary to track stamina and time for each segment
    # We'll use a list of dictionaries for efficient updates

    dp = [{} for _ in range(n + 1)]
    dp[0][0] = 0  # at start of segment 0, stamina 0, time 0

    for i in range(n):
        segment_length = lengths[i]
        segment_type = terrain[i]

        # Update dp[i+1] based on dp[i]
        for stamina, time in dp[i].items():
            if segment_type == 'G':
                # We can walk x meters, then fly (segment_length - x) meters
                # Total cost: segment_length + 4x
                # New stamina: stamina + 2x - segment_length
                # x can be in [0, segment_length]

                # To maximize stamina, we should walk as much as possible
                # But we also need to consider flying later

                # Actually, we should consider all possible x that maintain stamina >= 0
                for x in range(segment_length + 1):
                    cost = segment_length + 4 * x
                    new_stamina = stamina + 2 * x - segment_length
                    if new_stamina >= 0:
                        if new_stamina in dp[i+1]:
                            dp[i+1][new_stamina] = min(dp[i+1][new_stamina], time + cost)
                        else:
                            dp[i+1][new_stamina] = time + cost
            elif segment_type == 'W':
                # Swim x meters, then fly (segment_length - x) meters
                for x in range(segment_length + 1):
                    cost = segment_length + 2 * x
                    new_stamina = stamina + 2 * x - segment_length
                    if new_stamina >= 0:
                        if new_stamina in dp[i+1]:
                            dp[i+1][new_stamina] = min(dp[i+1][new_stamina], time + cost)
                        else:
                            dp[i+1][new_stamina] = time + cost
            elif segment_type == 'L':
                # Only fly, no walking/swimming
                cost = segment_length
                new_stamina = stamina - segment_length
                if new_stamina >= 0:
                    if new_stamina in dp[i+1]:
                        dp[i+1][new_stamina] = min(dp[i+1][new_stamina], time + cost)
                    else:
                        dp[i+1][new_stamina] = time + cost

    # After processing all segments, we need to consider flying over the last segment
    # But we also need to consider the possibility of flying over lava segments
    # Actually, we already handled all segments

    # Find the minimum time among all possible stamina values at the end
    # We don't need stamina at the end

    min_time = float('inf')
    for stamina, time in dp[n].items():
        min_time = min(min_time, time)

    print(min_time)

if __name__ == '__main__':
    solve()
