import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        a = [int(next(it)) for _ in range(n)]

        # Count frequencies
        freq = {}
        for num in a:
            freq[num] = freq.get(num, 0) + 1

        max_len = 0

        # Try all possible pairs of left/right element a and middle element b
        for a_elem in freq:
            a_positions = [i for i, num in enumerate(a) if num == a_elem]
            a_count = len(a_positions)

            # Case 1: middle is the same as a (no middle block)
            max_len = max(max_len, 2 * a_count)

            # Case 2: middle is a different element
            for b_elem in freq:
                if b_elem == a_elem:
                    continue

                # Try different splits of a_positions into left and right
                for left_size in range(0, a_count + 1):
                    # We need at least 1 position left for the middle
                    if left_size > a_count - left_size:
                        continue

                    left = a_positions[:left_size]
                    right = a_positions[left_size:]

                    # If there are no right elements, skip
                    if not right:
                        continue

                    # Middle positions are those not in left or right and not a_elem
                    # Actually, the middle can be any element, not just b_elem
                    # So we count all positions between left and right that are not a_elem

                    # Special case: if left is empty, the middle starts at 0
                    # If right is empty, the middle ends at n-1

                    # Find the range between left and right
                    if not left:
                        first_available = 0
                    else:
                        first_available = left[-1] + 1

                    if not right:
                        last_available = n - 1
                    else:
                        last_available = right[0] - 1

                    # Middle positions are those in [first_available, last_available] that are not a_elem
                    middle_positions = []
                    for i in range(first_available, last_available + 1):
                        if a[i] != a_elem:
                            middle_positions.append(a[i])

                    middle_count = len(middle_positions)

                    # Total length
                    total = left_size + middle_count + (a_count - left_size)
                    max_len = max(max_len, total)

        print(max_len)

if __name__ == "__main__":
    solve()
