def deviation(p, shift):
    n = len(p)
    total = 0
    for i in range(n):
        # Original index i (0-indexed)
        # New position after shift
        if i + shift <= n - 1:
            new_pos = i + shift + 1  # 1-indexed
        else:
            new_pos = i - (n - shift) + 1  # 1-indexed
        total += abs(p[i] - new_pos)
    return total

