import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])
    m = int(data[2])
    nums = list(map(int, data[3:3+n]))

    # Count occurrences of each remainder
    remainder_counts = {}
    for num in nums:
        r = num % m
        remainder_counts[r] = remainder_counts.get(r, 0) + 1

    # Find if any remainder has at least k occurrences
    selected_remainder = None
    for r, count in remainder_counts.items():
        if count >= k:
            selected_remainder = r
            break

    if selected_remainder is None:
        print("No")
    else:
        print("Yes")
        # Collect k numbers with the selected remainder
        result = [str(num) for num in nums if num % m == selected_remainder][:k]
        print(" ".join(result))

if __name__ == "__main__":
    solve()
"}

