import sys
import math
from bisect import bisect_left, bisect_right

# Precompute smallest prime factor (SPF) for factorization up to 1e5
max_x = 100005
spf = list(range(max_x + 1))
for i in range(2, int(math.isqrt(max_x)) + 1):
    if spf[i] == i:
        for j in range(i * i, max_x + 1, i):
            if spf[j] == j:
                spf[j] = i

def get_divisors(x):
    divs = set()
    if x == 0:
        return divs
    # Factor x using SPF
    factors = {}
    while x > 1:
        p = spf[x]
        cnt = 0
        while x % p == 0:
            x //= p
            cnt += 1
        factors[p] = cnt
    # Generate divisors
    divs = [1]
    for p, cnt in factors.items():
        new_divs = []
        for d in divs:
            val = d
            for _ in range(cnt):
                val *= p
                new_divs.append(val)
        divs += new_divs
    return sorted(divs)

# Read input
n = int(sys.stdin.readline())

# Maintain presence and multiples of each divisor
present = [False] * max_x
# Dictionary: divisor -> sorted list of multiples seen
multiples_of_d = {}

for i in range(1, n + 1):
    line = sys.stdin.readline()
    while line.strip() == '':
        line = sys.stdin.readline()
    xi, yi = map(int, line.strip().split())
    L = xi - yi
    R = xi - 1

    # Find divisors of xi
    divisors = get_divisors(xi)
    count = len(divisors)

    for d in divisors:
        # Check if any multiple of d in [L, R] is present
        m = ((L + d - 1) // d) * d  # smallest multiple >= L
        if m > R:
            continue
        # Binary search in multiples_of_d for d
        if d not in multiples_of_d:
            continue
        lst = multiples_of_d[d]
        idx = bisect_left(lst, m)
        if idx < len(lst) and lst[idx] <= R:
            count -= 1

    print(count)

    # Add xi to presence and multiples_of_d
    if xi <= max_x - 1:
        present[xi] = True
        for d in divisors:
            if d not in multiples_of_d:
                multiples_of_d[d] = []
            multiples_of_d[d].append(xi)

# Now, we need to sort each list in multiples_of_d for binary search
for d in multiples_of_d:
    multiples_of_d[d].sort()
