# Function to check if first is a prefix of second, and second is a suffix
# Returns True if first is a subsequence of main, and second is a subsequence of the remaining part

def check_sequence(first, second, main):
    # Check if first is a subsequence of main
    i = 0
    for ch in main:
        if i < len(first) and ch == first[i]:
            i += 1
    if i != len(first):
        return False

    # Check if second is a subsequence of the remaining part
    # After finding first, we start from the position after the end of first
    # For this, we need to track the position more carefully

    # Alternative approach: check if second is a subsequence of the main string
    # starting from the position after the end of first

    # Find the end index of first in main
    first_len = len(first)
    end_first = 0
    for i in range(len(main)):
        if main[i] == first[end_first]:
            end_first += 1
            if end_first == first_len:
                # First ends at position i
                break

