import sys

def is_good(a, i, n):
    """Check if the suffix a[i:] is good"""
    left = i
    right = n - 1
    c = []

    while left <= right:
        # The next element we take must be >= last element of c (if any)
        if not c:
            # c is empty, take the smaller of the two ends
            if a[left] <= a[right]:
                c.append(a[left])
                left += 1
            else:
                c.append(a[right])
                right -= 1
        else:
            # c is not empty, find the smallest element >= last element of c
            # that we can take
            last = c[-1]
            options = []
            if a[left] >= last:
                options.append((a[left], left, 'left'))
            if a[right] >= last:
                options.append((a[right], right, 'right'))

            if not options:
                return False

            # Take the smallest option
            val, pos, side = min(options)
            if side == 'left':
                c.append(val)
                left += 1
            else:
                c.append(val)
                right -= 1

    return True

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        a = [int(next(it)) for _ in range(n)]

        # Find the smallest prefix to erase
        ans = n  # Worst case: erase all
        for i in range(n + 1):
            if is_good(a, i, n):
                ans = i
                break

        print(ans)

if __name__ == "__main__":
    solve()
