    # Count how many numbers have each highest set bit
    bit_counts = {}
    for num in a:
        highest_bit = 0
        # Find the highest set bit
        for i in range(32):
            if num & (1 << i):
                highest_bit = i
        # Since we only care about the value of the highest bit, we can just use the value
        # Actually, we can find it more efficiently by finding the highest bit position and then shifting
        # But for simplicity, we'll just keep track of the count for each bit value

