        highest_bit_val = 1
        while highest_bit_val <= num:
            highest_bit_val <<= 1
        highest_bit_val >>= 1

        if highest_bit_val in bit_counts:
            bit_counts[highest_bit_val] += 1
        else:
            bit_counts[highest_bit_val] = 1

    # Count valid pairs
    answer = 0
    for count in bit_counts.values():
        answer += count * (count - 1) // 2

    print(answer)
