import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    t = int(data[idx])
    idx += 1

    results = []

    for _ in range(t):
        n = int(data[idx]); m = int(data[idx+1]); x = int(data[idx+2]); y = int(data[idx+3])
        idx += 4

        cost = 0

        for _ in range(n):
            row = data[idx]
            idx += 1

            if y < 2 * x:
                # Prefer 1x2 tiles where adjacent pairs exist
                i = 0
                while i < m:
                    if row[i] == '.':
                        if i + 1 < m and row[i+1] == '.':
                            # Use 1x2 tile
                            cost += y
                            i += 2
                        else:
                            # Use 1x1 tile
                            cost += x
                            i += 1
                    else:
                        i += 1
            else:
                # Only use 1x1 tiles
                count = row.count('.')
                cost += count * x

        results.append(str(cost))

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
