n, m, color = input().split()
grid = [list(input().strip()) for _ in range(int(n))]

# Find all desks
desk_cells = {}
for i in range(n):
    for j in range(m):
        if grid[i][j] != '.':
            # This is a new desk, find its rectangle
            letter = grid[i][j]
            if letter not in desk_cells:
                # Find the rectangle boundaries
                min_row, max_row = i, i
                min_col, max_col = j, j

                # Expand down
                while max_row + 1 < n and grid[max_row + 1][j] == letter:
                    max_row += 1

                # Expand up
                while min_row - 1 >= 0 and grid[min_row - 1][j] == letter:
                    min_row -= 1

                # Expand right
                while max_col + 1 < m and grid[i][max_col + 1] == letter:
                    max_col += 1

                # Expand left
                while min_col - 1 >= 0 and grid[i][min_col - 1] == letter:
                    min_col -= 1

                desk_cells[letter] = (min_row, max_row, min_col, max_col)

# Find President's desk
president_cells = desk_cells[color]
pres_row_start, pres_row_end, pres_col_start, pres_col_end = president_cells

deputies = 0

# Check each other desk
for letter, (row_start, row_end, col_start, col_end) in desk_cells.items():
    if letter == color:
        continue  # Skip the President's own desk

    # Check if this desk shares a side with the President's desk
    # They share a side if:
    # - They share a row and their column ranges are adjacent
    # - They share a column and their row ranges are adjacent

    # Check row sharing
    if pres_row_start == row_start and pres_row_end == row_end:
        # Same row, check if adjacent columns
        if abs(pres_col_end - col_start) == 1 or abs(pres_col_start - col_end) == 1:
            deputies += 1
    elif pres_row_start == row_start + 1 or pres_row_end == row_start - 1:
        # Adjacent rows, check if same column
        # The desks share a column if the President's column range includes the other desk's column
        if pres_col_start <= col_end and pres_col_end >= col_start:
            deputies += 1

    # Check column sharing
    if pres_col_start == col_start and pres_col_end == col_end:
        # Same column, check if adjacent rows
        if abs(pres_row_end - row_start) == 1 or abs(pres_row_start - row_end) == 1:
            deputies += 1
    elif pres_col_start == row_start + 1 or pres_col_end == row_start - 1:
        # Adjacent columns, check if same row
        if pres_row_start <= row_end and pres_row_end >= row_start:
            deputies += 1

print(deputies)
