def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # Helper to compute subset sums
    def compute_subsets(arr):
        from itertools import combinations
        sums = set()

        # For all non-empty proper subsets
        for k in range(1, n):
            for indices in combinations(range(n), k):
                total = sum(arr[i] for i in indices)
                sums.add(total)

        return sums

    # Brute force search with backtracking
    def backtrack(position, used, current, all_sums):
        if position == n:
            # Check if all subset sums are different
            sums = compute_subsets(current)
            if len(sums) == n * (n-1) // 2:
                # All subset sums are different
                return current
            return None

        for i in range(n):
            if not used[i]:
                # Try placing a[i] at current position
                result = backtrack(position + 1, used + (True,) + (used[i+1:]), current + [a[i]], all_sums)
                if result:
                    return result

        return None

    answer = backtrack(0, tuple([False]*n), [], None)

    if answer:
        print(' '.join(map(str, answer)))
    else:
        print(-1)

