import sys

def count_lucky_digits(n):
    """Count how many lucky digits (4 or 7) are in n"""
    count = 0
    while n > 0:
        if n % 10 in {4, 7}:
            count += 1
        n //= 10
    return count

def solve():
    m = int(sys.stdin.readline())

    # Count how many numbers have exactly k lucky digits
    counts = {}
    for num in range(1, m + 1):
        k = count_lucky_digits(num)
        if k not in counts:
            counts[k] = 0
        counts[k] += 1

    MOD = 1000000007
    result = 0

    # Factorial of 6
    fact6 = 1
    for i in range(1, 7):
        fact6 = fact6 * i % MOD

    # Try each possible number of lucky digits for LEPP
    for k in counts:
        # LEPP has k lucky digits
        # Other 6 parties must have at most k-1 lucky digits in total

        # Get the remaining numbers
        remaining = {}
        for l in counts:
            if l == k:
                remaining[l] = counts[l] - 1
            else:
                remaining[l] = counts[l]

        # Count of numbers with exactly l lucky digits remaining
        c = [remaining[l] for l in sorted(remaining)]
        lucky_digits = [l for l in sorted(remaining)]

        # DP table: dp[a][b] = number of ways to choose a numbers with total lucky digits sum b
        dp = [[0] * (k) for _ in range(7)]
        dp[0][0] = 1

        # Fill DP
        for idx in range(len(lucky_digits)):
            l = lucky_digits[idx]
            cnt = c[idx]

            # Update DP in reverse order to avoid overcounting
            for a in range(6, -1, -1):
                for b in range(k):
                    if dp[a][b] > 0:
                        if a + 1 <= 6 and b + l < k:
                            dp[a+1][b+l] = (dp[a+1][b+l] + dp[a][b] * cnt) % MOD

        # Add to result: LEPP choices * valid 6-element subsets * 6!
        result = (result + counts[k] * dp[6][k-1] * fact6) % MOD

    print(result)

solve()
