import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    constraints = []
    for _ in range(m):
        l = int(next(it))
        r = int(next(it))
        q = int(next(it))
        constraints.append((l, r, q))

    # prefix_and[i] = AND of a[1..i]
    prefix_and = [0] * (n + 1)

    # Process constraints to determine prefix_and
    for l, r, q in constraints:
        prefix_and[r] = q | prefix_and[l - 1]

    # Reconstruct a[i]
    a = []
    for i in range(1, n + 1):
        a.append(prefix_and[i] & ~prefix_and[i - 1])

    # Verify prefix AND property
    valid = True
    for i in range(1, n + 1):
        if (prefix_and[i - 1] & a[i]) != prefix_and[i]:
            valid = False
            break

    # Verify all constraints
    if valid:
        for l, r, q in constraints:
            and_val = a[l - 1]
            for i in range(l, r + 1):
                and_val &= a[i]
            if and_val != q:
                valid = False
                break

    if valid:
        print("YES")
        print(' '.join(map(str, a)))
    else:
        print("NO")

if __name__ == "__main__":
    solve()
"}

