import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        x = int(next(it))
        a = [int(next(it)) for _ in range(n)]

        operations = 0

        # Traverse from left to right
        for i in range(n):
            if a[i] > x:
                # Swap a[i] and x
                a[i], x = x, a[i]
                operations += 1

        # Check if the sequence is sorted
        sorted_flag = True
        for i in range(n - 1):
            if a[i] > a[i + 1]:
                sorted_flag = False
                break

        if sorted_flag:
            print(operations)
        else:
            print(-1)

if __name__ == "__main__":
    solve()
"}

