    if not data:
        return

    idx = 0
    t = int(data[idx])
    idx += 1

    for _ in range(t):
        n = int(data[idx])
        x = int(data[idx + 1])
        idx += 2

        a = [int(data[idx + i]) for i in range(n)]
        idx += n

        swaps = 0

        # Greedy approach: iterate from left to right
        for i in range(n):
            if a[i] > x:
                # Swap a[i] with x
                a[i], x = x, a[i]
                swaps += 1

        # Check if the sequence is sorted
        # Actually, we just need to check if the array is sorted
        is_sorted = True
        for i in range(n - 1):
            if a[i] > a[i + 1]:
                is_sorted = False
                break

        if is_sorted:
            print(swaps)
        else:
            print(-1)

if __name__ == "__main__":
