    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    result = []

    for _ in range(t):
        n = int(next(it))
        a = list(map(int, [next(it) for _ in range(n)]))

        # Count occurrences of each element
        freq = [0] * 27
        for num in a:
            freq[num] += 1

        max_len = 0

        # Try all pairs (a, b)
        for a_val in range(1, 27):
            for b_val in range(1, 27):
                # For a given a and b, try all ways to take a's from beginning and end
                # We need at least one a block on each side, so i ≥ 1, j ≥ 1
                for i in range(1, freq[a_val] + 1):
                    # Find the positions of the first i a's
                    count = 0
                    pos_last = -1

                    # Find the position of the last a in the first i a's
                    for idx, num in enumerate(a):
                        if num == a_val:
                            count += 1
                            if count == i:
                                pos_last = idx

                    if count < i:
                        continue

                    # Now try all j ≥ 1
                    for j in range(1, freq[a_val] + 1):
                        # Find the positions of the last j a's
                        count = 0
                        pos_first_end = -1

                        # Count from the end
                        for idx in range(len(a)-1, -1, -1):
                            if a[idx] == a_val:
                                count += 1
                                if count == j:
                                    pos_first_end = idx

                        if count < j:
                            continue

                        # Ensure the a's from beginning and end are separate
                        if pos_last >= pos_first_end:
                            continue

                        # Count b's in the middle
                        b_count = 0
                        for idx in range(pos_last + 1, pos_first_end):
                            if a[idx] == b_val:
                                b_count += 1

                        total = i + b_count + j
                        max_len = max(max_len, total)

        result.append(str(max_len))

    sys.stdout.write("\n".join(result))

if __name__ == "__main__":
