from itertools import combinations, permutations

def compute_b(t):
    """Compute the b array for string t"""
    m = len(t)
    b = [0] * m

    for i in range(m):
        for j in range(m):
            if t[j] > t[i]:
                b[i] += abs(i - j)

    return b

def solve():
    q = int(input())

    for _ in range(q):
        s = input().strip()
        m = int(input())
        b_list = list(map(int, input().split()))

        # Try all combinations of m letters from s
        found = False

        for combo in combinations(s, m):
            # Try all permutations of this combination
            for perm in permutations(combo):
                # Check if this permutation matches the b array
                if compute_b(perm) == b_list:
                    print(''.join(perm))
                    found = True
                    break
            if found:
                break

solve()
