from itertools import combinations

def compute_b(t):
    """Compute the b array for string t"""
    m = len(t)
    b = [0] * m

    for i in range(m):
        for j in range(m):
            if t[j] > t[i]:
                b[i] += abs(i - j)

    return b

def solve():
    q = int(input())

    for _ in range(q):
        s = input().strip()
        m = int(input())
        b_list = list(map(int, input().split()))

        # Try all combinations of m letters from s
        for combo in combinations(s, m):
            # Try to find a permutation of this combination that matches b_list
            # Since we need only one solution, we can try a greedy approach
            # Start by finding which character should go in each position

            # The character with max b value should be the smallest (since it has many greater characters)
            # The character with min b value should be the largest (since it has few or no greater characters)

            char_to_b = {}
            for i, char in enumerate(combo):
                char_to_b[char] = b_list[i]

            # Sort by b value, then by character to get a candidate order
            sorted_chars = sorted(combo, key=lambda c: (-char_to_b[c], c))

            if compute_b(sorted_chars) == b_list:
                print(''.join(sorted_chars))
                break

            # Try sorting by b value ascending, then by character
            sorted_chars = sorted(combo, key=lambda c: (char_to_b[c], c))

            if compute_b(sorted_chars) == b_list:
                print(''.join(sorted_chars))
                break

solve()
