def can_pack(objects, boxes, box_size):
    """Check if we can pack all objects using greedy algorithm"""
    remaining = box_size
    boxes_used = 1

    for obj in objects:
        if obj <= remaining:
            remaining -= obj
        else:
            # Need new box
            boxes_used += 1
            if boxes_used > boxes:
                return False
            remaining = box_size - obj

    return True

def max_objects_packed(n, m, k, a):
    """Find maximum number of objects that can be packed"""
    # Try keeping objects starting from position i (0-indexed)
    for i in range(n):
        # Check if we can pack objects from position i to n-1
        if can_pack(a[i:], m, k):
            return n - i

    # If no configuration works, return 0
    return 0

