def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))

        from collections import defaultdict
        freq = defaultdict(int)
        for num in a:
            freq[num] += 1

        max_len = 0

        # Case 1: Only one block (either a or b)
        for num in freq:
            max_len = max(max_len, freq[num])

        # Case 2: Three blocks (a...a, b...b, a...a)
        # For each possible middle block b
        for middle in freq:
            # Find first and last positions of b
            first_b = -1
            last_b = -1
            for i, num in enumerate(a):
                if num == middle:
                    first_b = i
                    last_b = i
                    break
            for i, num in enumerate(a):
                if num == middle:
                    last_b = i

            # Count a's before first b
            a_count_before = 0
            for i in range(first_b):
                if a[i] == middle:
                    a_count_before += 1

            # Count a's after last b
            a_count_after = 0
            for i in range(last_b + 1, n):
                if a[i] == middle:
                    a_count_after += 1

            # If we can take a's from both sides
            if a_count_before > 0 and a_count_after > 0:
                total = a_count_before + freq[middle] + a_count_after
                max_len = max(max_len, total)

