import sys

class TrieNode:
    def __init__(self):
        self.children = [None, None]
        self.count = 0

class Trie:
    def __init__(self):
        self.root = TrieNode()
        self.max_bit = 25  # since pi, li <= 10^8, we need 27 bits

    def insert(self, x):
        node = self.root
        for i in range(self.max_bit, -1, -1):
            bit = (x >> i) & 1
            if not node.children[bit]:
                node.children[bit] = TrieNode()
            node = node.children[bit]
            node.count += 1

    def remove(self, x):
        node = self.root
        for i in range(self.max_bit, -1, -1):
            bit = (x >> i) & 1
            node = node.children[bit]
            node.count -= 1

    def query(self, pi, li):
        # Count x such that (x XOR pi) <= li
        # This means x & (~li) == pi & (~li)

        # We'll use a DFS approach through the trie
        count = 0
        stack = [(self.root, 0, self.max_bit)]  # (node, depth, current bit)

        while stack:
            curr, depth, i = stack.pop()

            # If we're at a leaf, add its count
            if not curr.children[0] and not curr.children[1]:
                count += curr.count
                continue

            # Check if the condition is satisfied up to this bit
            # (x XOR pi) <= li means x & (~li) == pi & (~li)
            # At this bit, x bit and pi bit must match if li bit is 0
            pi_bit = (pi >> i) & 1
            li_bit = (li >> i) & 1

            # If li bit is 0, x bit must equal pi bit
            # If li bit is 1, x bit can be anything

            # Check if we can go to child 0
            if li_bit == 0:
                # x bit must equal pi bit, which could be 0 or 1
                child = curr.children[0] if pi_bit == 0 else curr.children[1]
                if child:
                    stack.append((child, depth + 1, i - 1))
            else:
                # li bit is 1, can go to both children
                for bit in [0, 1]:
                    child = curr.children[bit]
                    if child:
                        stack.append((child, depth + 1, i - 1))
        return count

    def size(self):
        return self.root.count

    def is_empty(self):
        return self.size() == 0


def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    q = int(next(it))

    trie = Trie()

    for _ in range(q):
        t = int(next(it))
        if t == 1:
            pi = int(next(it))
            trie.insert(pi)
        elif t == 2:
            pi = int(next(it))
            trie.remove(pi)
        elif t == 3:
            pi = int(next(it))
            li = int(next(it))

            # Count x such that (x XOR pi) <= li
            count = trie.query(pi, li)
            print(count)

if __name__ == "__main__":
    solve()
"}

