def solve():
    # Read all input at once
    data = []
    while True:
        try:
            line = input().strip()
            if line:
                data.extend(line.split())
        except EOFError:
            break

    if not data:
        return

    n = int(data[0])
    m = int(data[1])

    edges = []
    idx = 2

    for _ in range(m):
        u = int(data[idx])
        v = int(data[idx+1])
        g = int(data[idx+2])
        l = int(data[idx+3])
        edges.append((u, v, g, l))
        idx += 4

    # Build adjacency list
    adj = [[] for _ in range(n+1)]

    for u, v, g, l in edges:
        adj[u].append((v, g, l))
        adj[v].append((u, g, l))

    # Try assigning values using DFS
    values = [0] * (n + 1)

    def dfs(node, parent, current_value):
        # Assign value to current node
        values[node] = current_value

        # Try all neighbors
        for neighbor, g, l in adj[node]:
            if neighbor == parent:
                continue

            # Compute target product
            target = l // g

            # Check if target is valid
            if target * g != l:
                return False  # Contradiction

            # Get possible pairs (a, b) for this edge
            if values[neighbor] == 0:
                # Neighbor has no value yet
                # Try all possible pairs where product = target and GCD = 1
                for a in range(1, int(target**0.5) + 1):
                    if target % a == 0:
                        b = target // a
                        if gcd(a, b) == 1:
                            # Try both orderings
                            if dfs(neighbor, node, g * a):
                                return True
                            if dfs(neighbor, node, g * b):
                                return True
                return False
            else:
                # We have a value for neighbor
                # current_value is the value of current node
                # values[neighbor] is the value of neighbor

                # Check product condition
                if current_value * values[neighbor] != g * l:
                    return False

                # Check GCD condition
                if gcd(current_value, values[neighbor]) != g:
                    return False
        return True

    # Try starting from node 1 with value 1
    if dfs(1, -1, 1):
        print("YES")
        print(' '.join(str(values[i]) for i in range(1, n+1)))
    else:
        print("NO")

