m = int(input().split()[1])

constraints = []
for _ in range(m):
    li, ri, qi = map(int, input().split())
    constraints.append((li, ri, qi))

# Start with all bits unset in all elements
a = [0] * n

# For each bit position from 0 to 29
for bit in range(30):
    # Try to set this bit in all elements
    # Check if this is valid for all constraints
    valid = True
    for li, ri, qi in constraints:
        # If the bit is set in qi, all elements in [li, ri] must have this bit set
        if (qi >> bit) & 1:
            continue
        # If the bit is not set in qi, at least one element in [li, ri] must have this bit unset
        # Currently, we're trying to set all elements, so we need to check if this is valid
        # If all elements in [li, ri] have this bit set, it's invalid
        if all((a[i] >> bit) & 1 for i in range(li - 1, ri)):
            valid = False
            break

    if valid:
        # Set this bit in all elements
        for i in range(n):
            a[i] |= (1 << bit)

# Check if the final array satisfies all constraints
all_satisfied = True
for li, ri, qi in constraints:
    and_val = 0
    for i in range(li - 1, ri):
        and_val &= a[i]
    if and_val != qi:
        all_satisfied = False
        break

if all_satisfied:
    print("YES")
    print(' '.join(map(str, a)))
else:
    print("NO")
"}

