from collections import Counter

def solve():
    a = input().strip()
    b = input().strip()

    count_a = Counter(a)
    count_b = Counter(b)

    extra_4s = count_a.get('4', 0) - count_b.get('4', 0)
    extra_7s = count_a.get('7', 0) - count_b.get('7', 0)

    if extra_4s > 0 or extra_7s > 0:
        answer = max(extra_4s, extra_7s)
    else:
        # Count differing positions
        k = 0
        for i in range(len(a)):
            if a[i] != b[i]:
                k += 1
        answer = k // 2 + (1 if k % 2 else 0)  # ceil(k / 2)

    print(answer)

if __name__ == "__main__":
    solve()
"}

