        reached = False

        while True:
            # Check if we've reached b
            if current == b:
                reached = True
                break

            # If we can remove a character from the front
            if len(current) > 0:
                # Remove first character
                current = current[1:]
            else:
                # If we can't remove and we've reached max length
                if len(current) >= len(b) and current[:len(b)] == b[:len(b)]:
