t = int(input())
for _ in range(t):
    n = int(input())
    a = list(map(int, input().split()))

    from collections import defaultdict
    pos = defaultdict(list)
    for i, num in enumerate(a):
        pos[num].append(i)

    max_len = 0

    # Consider single block palindrome (all a's)
    for num in pos:
        max_len = max(max_len, len(pos[num]))

    # Consider three blocks palindrome with two distinct elements
    for a_val in pos:
        a_indices = pos[a_val]
        for b_val in pos:
            if a_val == b_val:
                continue  # already considered single block
            b_indices = pos[b_val]

            # Try using k a's at the beginning and k a's at the end
            for k in range(len(a_indices) // 2 + 1):
                if k == 0:
                    # No a's at the beginning or end
                    cnt = len(b_indices)
                    max_len = max(max_len, cnt)
                else:
                    # a's at the beginning: first k a's
                    # a's at the end: last k a's
                    # The b's should be between the last a at the beginning and first a at the end
                    # Positions of a's at the beginning: a_indices[0..k-1]
                    # Positions of a's at the end: a_indices[-k..-1]
                    # So b's should be > a_indices[k-1] and < a_indices[-k]
                    cnt = 0
                    for b_idx in b_indices:
                        if a_indices[k-1] < b_idx < a_indices[-k]:
                            cnt += 1

                    max_len = max(max_len, 2 * k + cnt)

    print(max_len)
