import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, m, a, b = map(int, data)
    max_k = (n + m - 1) // m
    min_cost = float('inf')
    for k in range(max_k + 1):
        extra = max(0, n - k * m)
        cost = k * b + extra * a
        if cost < min_cost:
            min_cost = cost
    print(min_cost)

if __name__ == "__main__":
    main()
